#!/usr/bin/env bash
# Wraps deploy/monitoring/alerts.rules.yml (the single source of the alert rules) into a PrometheusRule for
# the prometheus-operator: deploy/k8s/components/monitoring/prometheusrule.yaml.
#   deploy/scripts/render-prometheusrule.sh          # rewrite
#   deploy/scripts/render-prometheusrule.sh --check  # CI: fail if stale
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
TARGET="$ROOT/deploy/k8s/components/monitoring/prometheusrule.yaml"
render() {
  cat <<'HEAD'
# GENERATED by deploy/scripts/render-prometheusrule.sh from deploy/monitoring/alerts.rules.yml -- do not edit.
apiVersion: monitoring.coreos.com/v1
kind: PrometheusRule
metadata:
  name: openjcockpit
  labels: {release: prometheus}
spec:
HEAD
  grep -v '^#' "$ROOT/deploy/monitoring/alerts.rules.yml" | sed 's/^/  /'
}
if [ "${1:-}" = "--check" ]; then
  diff -q <(render) "$TARGET" >/dev/null || { echo "prometheusrule.yaml is stale: run deploy/scripts/render-prometheusrule.sh"; exit 1; }
  echo "prometheusrule up to date"
else
  mkdir -p "$(dirname "$TARGET")"; render > "$TARGET"; echo "wrote ${TARGET#"$ROOT"/}"
fi
